CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, display_name text NOT NULL, role text NOT NULL CHECK (role IN ('owner','admin','school_user')), status text NOT NULL DEFAULT 'active', school_id uuid NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS schools (id uuid PRIMARY KEY, name text NOT NULL, code text NOT NULL UNIQUE, region text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sites (id uuid PRIMARY KEY, school_id uuid NOT NULL REFERENCES schools(id), name text NOT NULL, capacity_mwp numeric(12,4) NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Bangkok', status text NOT NULL DEFAULT 'online', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE sites ADD COLUMN IF NOT EXISTS latitude numeric(10,7);
ALTER TABLE sites ADD COLUMN IF NOT EXISTS longitude numeric(10,7);
CREATE TABLE IF NOT EXISTS gateways (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES sites(id), name text NOT NULL, protocol text NOT NULL, endpoint text NOT NULL, status text NOT NULL DEFAULT 'offline', last_seen_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS devices (id uuid PRIMARY KEY, gateway_id uuid NOT NULL REFERENCES gateways(id), site_id uuid NOT NULL REFERENCES sites(id), name text NOT NULL, device_type text NOT NULL, model text NOT NULL, serial_number text NOT NULL UNIQUE, slave_id integer NULL, status text NOT NULL DEFAULT 'online');
CREATE TABLE IF NOT EXISTS register_mapping_versions (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id), semantic_field text NOT NULL, register_address text NOT NULL, data_type text NOT NULL, signed boolean NOT NULL DEFAULT false, byte_order text NOT NULL, scale numeric(20,8) NOT NULL, unit text NOT NULL, polling_interval_seconds integer NOT NULL DEFAULT 60, quality_rule jsonb NOT NULL DEFAULT '{}'::jsonb, effective_from timestamptz NOT NULL, effective_to timestamptz NULL);
CREATE TABLE IF NOT EXISTS billing_meters (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES sites(id), device_id uuid NOT NULL REFERENCES devices(id), semantic_field text NOT NULL DEFAULT 'total_energy', active boolean NOT NULL DEFAULT true, UNIQUE(site_id, device_id, semantic_field));
CREATE TABLE IF NOT EXISTS telemetry_aggregate (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES sites(id), device_id uuid NOT NULL REFERENCES devices(id), semantic_field text NOT NULL, bucket text NOT NULL CHECK (bucket IN ('15m','hour','day','month')), bucket_start timestamptz NOT NULL, value numeric(24,8) NOT NULL, sample_count integer NOT NULL, quality text NOT NULL CHECK (quality IN ('complete','partial','estimated','invalid')), UNIQUE(device_id, semantic_field, bucket, bucket_start));
CREATE INDEX IF NOT EXISTS telemetry_aggregate_site_bucket_idx ON telemetry_aggregate(site_id, semantic_field, bucket, bucket_start);
CREATE TABLE IF NOT EXISTS contracts (id uuid PRIMARY KEY, school_id uuid NOT NULL REFERENCES schools(id), site_id uuid NOT NULL REFERENCES sites(id), version integer NOT NULL, start_date date NOT NULL, end_date date NULL, status text NOT NULL DEFAULT 'active', payment_terms text NOT NULL, signer_name text NOT NULL, attachment_key text NULL, UNIQUE(site_id, version));
CREATE TABLE IF NOT EXISTS rate_versions (id uuid PRIMARY KEY, contract_id uuid NOT NULL REFERENCES contracts(id), effective_from date NOT NULL, effective_to date NULL, rate_type text NOT NULL DEFAULT 'fixed_kwh', rate numeric(20,8) NOT NULL, currency text NOT NULL DEFAULT 'THB');
CREATE TABLE IF NOT EXISTS billing_cycles (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES sites(id), period_start date NOT NULL, period_end date NOT NULL, cutoff_time timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending_review', quality text NOT NULL, opening_energy numeric(24,8) NOT NULL, closing_energy numeric(24,8) NOT NULL, consumed_kwh numeric(24,8) NOT NULL, rate numeric(20,8) NOT NULL, amount numeric(24,8) NOT NULL, UNIQUE(site_id, period_start, period_end));
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES sites(id), billing_cycle_id uuid NULL REFERENCES billing_cycles(id), document_type text NOT NULL CHECK (document_type IN ('invoice','receipt','billing_statement')), document_number text NULL UNIQUE, status text NOT NULL DEFAULT 'draft', issue_date date NULL, amount numeric(24,8) NULL, file_key text NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY, billing_cycle_id uuid NOT NULL REFERENCES billing_cycles(id), status text NOT NULL DEFAULT 'pending', paid_at timestamptz NULL, evidence_key text NULL, note text NULL);
CREATE TABLE IF NOT EXISTS alerts (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES sites(id), gateway_id uuid NULL REFERENCES gateways(id), severity text NOT NULL, title text NOT NULL, detail text NOT NULL, status text NOT NULL DEFAULT 'open', occurred_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS alerts_site_occurred_idx ON alerts(site_id, occurred_at DESC);
ALTER TABLE telemetry_raw ADD COLUMN IF NOT EXISTS site_id uuid NULL REFERENCES sites(id);
ALTER TABLE telemetry_raw ADD COLUMN IF NOT EXISTS semantic_field text NULL;
